 217   // Abstract-first CSR write with Program Buffer fallback.
 218   // Tries an abstract register write; if the DM signals cmderr, clears it,
 219   // stages the value in scratch_gpr via abstract GPR write, then executes a
 220   // one-instruction PB (`csrrw x0, csr, scratch_gpr`).  scratch_gpr defaults
 221   // to x5 (t0) which the GPR restore loop overwrites later.
 222   void write_csr_abstract_or_pb(uint16_t csr, uint64_t value,
 223                                  uint8_t scratch_gpr = 5)
 224   {
 225     write_64bit_register(regno_csr(csr), value);
 226     if ((bus_.read(kAbstractcs) & kAbstractcsCmderrMask) == 0u) return;
 227     bus_.write(kAbstractcs, kAbstractcsCmderrMask);  // W1C: clear sticky error
 228     write_64bit_register(regno_gpr(scratch_gpr), value);
 229     const std::array<uint32_t, 1> pb = { encode_csrrw(0, csr, scratch_gpr) };
 230     exec_progbuf(bus_, std::span<const uint32_t>{pb});
 231   }
