 233   // Write a CSR-addressable register and clear any cmderr the DM raised.
 234   // Used for CSRs whose abstract-access support may be implementation
 235   // dependent; a missing CSR mirrors as a no-op rather than blocking the
 236   // remaining writes.
 237   void write_csr_tolerant(uint16_t csr, uint64_t value)
 238   {
 239     write_64bit_register(regno_csr(csr), value);
 240     clear_cmderr_if_set();
 241   }
