 243   // abstractcs.cmderr is sticky per the Debug Spec - a subsequent command
 244   // is rejected until the bits are W1C-cleared. We tolerate per-register
 245   // failures (e.g. unimplemented FPR/CSR Abstract access) by clearing the
 246   // error before resuming so the hart isn't left in a stuck state.
 247   // B17: record the last observed non-zero cmderr and a clear count so a
 248   // partially-broken restore is observable via the public accessors
 249   // instead of silently swallowed.
 250   void clear_cmderr_if_set()
 251   {
 252     const auto status = bus_.read(kAbstractcs);
 253     const auto code = (status & kAbstractcsCmderrMask) >> 8;
 254     if (code != 0u) {
 255       last_observed_cmderr_ = code;
 256       ++cmderr_clear_count_;
 257       bus_.write(kAbstractcs, kAbstractcsCmderrMask);
 258     }
 259   }
