 267   // at least one abstract write tripped a sticky cmderr the restore
 268   // tolerated by clearing. cmderr_clear_count() is the total number of
 269   // such clears across all calls into clear_cmderr_if_set() this run.
 270   auto last_observed_cmderr() const -> uint32_t { return last_observed_cmderr_; }
 271   auto cmderr_clear_count() const -> uint64_t   { return cmderr_clear_count_; }
