 274 // Read a 64-bit hart register (GPR / FPR / CSR by abstract regno) over DMI
 275 // via an Abstract Command. Halts-and-reads contract: caller must have the
 276 // hart in the halted state. Shared with StateDrain (drain at exit). If
 277 // abstractcs.cmderr goes sticky after the command, the helper clears it and
 278 // reports nullopt rather than blocking the caller -- a missing CSR mirrors as
 279 // absent instead of corrupting the adjacent field.
 280 inline auto read_register_64_checked(DmiBus& bus, uint16_t regno,
 281                                      const char* poll_label
 282                                        = "read_register_64")
 283   -> std::optional<uint64_t>
 284 {
 285   using RD = ResumeDriver;
 286   bus.write(RD::kCommand,
 287             access_register_command(regno, AarSize::Bits64, /*write=*/false));
 288   poll_until_clear(bus, RD::kAbstractcs, RD::kAbstractcsBusy, poll_label);
 289   const auto status = bus.read(RD::kAbstractcs);
 290   if ((status & RD::kAbstractcsCmderrMask) != 0u) {
 291     bus.write(RD::kAbstractcs, RD::kAbstractcsCmderrMask);
 292     return std::nullopt;
 293   }
 294   const uint64_t lo = bus.read(RD::kData0);
 295   const uint64_t hi = bus.read(RD::kData1);
 296   return lo | (hi << 32);
 297 }
 298 
 299 inline auto read_register_64(DmiBus& bus, uint16_t regno,
 300                              const char* poll_label = "read_register_64")
 301   -> uint64_t
 302 {
 303   return read_register_64_checked(bus, regno, poll_label).value_or(0u);
 304 }
